package com.lolita.app.domain.model

import com.google.gson.Gson

/** Constraints for one assembled outfit, conditional on the actual selected roles. */
internal fun physicalWearingPrompt(rows: List<TryOnSelection>, instructions: String): String = buildString {
    val roles = rows.map { it.role }.toSet()
    appendLine("PHYSICAL WEARING PLAN: before rendering, analyse construction, supported volume, attachment, body contact and inside/outside occlusion, independent of reference upload order. Render one dressed body, never pasted flat cutouts. Fabric wraps underlying volumes with gravity, compression, contact shadows and preserved motifs. No solid intersections, floating parts or invented hidden construction. Naturally occluded items stay hidden; never force everything visible.")
    appendLine("Preserve identity, body shape, skeletal limb lengths and overall standing stance. Do not slim or lengthen legs. Only minimal footwear/holding adjustments below are allowed.")
    if (TryOnRole.PETTICOAT in roles)
        appendLine("PETTICOAT + SKIRT: internal support expands the compatible outer skirt in three dimensions; outer fabric rests on it, not two independent skirts. Keep support concealed unless explicitly and plausibly exposed. Respect cut, hem length and available fabric; never inflate fitted skirts or intersect support.")
    else appendLine("No petticoat is selected: retain evidenced fullness; invent no support.")
    if (TryOnRole.PETTICOAT in roles)
        appendLine("裙撑是主裙内部的隐藏支撑体，“穿上全部物品”不等于全部露出来。按腰围与服装构造匹配穿戴尺度，不按各产品在照片中的像素大小直接拼接。除非用户明确要求露出，裙撑不得在主裙下方变成第二条可见白裙；在面料和版型允许范围内把支撑体积传递给外裙，并保留主裙本身长度。")
    if (roles.any { it in setOf(TryOnRole.TOP, TryOnRole.MAIN, TryOnRole.BOTTOM, TryOnRole.OUTER, TryOnRole.WAIST) })
        appendLine("GARMENT LAYERS: use necklines/openings to resolve layers; blouse under open JSK, not over closed OP by default. Outerwear encloses inner sleeve/bodice volume; tucked fabric disappears inside waistband. Belts wrap dressed waist. Do not shorten or lift hems to show socks/shoes.")
    if (TryOnRole.WAIST in roles)
        appendLine("WAIST CONSTRUCTION: identify the photographed object, not its generic belt label. Preserve corset height, contoured edges, actual panel materials, elastic sides, original buckle/eyelet/lacing counts and chain anchors. Wrap the dressed natural waist in correct perspective, not the product camera angle. A wide cincher spans above/below that waist, compressing fabric and occluding the underlying bow/pattern; never shrink or lower it onto the skirt to keep that bow visible. Chains hang from their actual attachments. Preserve body proportions.")
    if (TryOnRole.WAIST in roles)
        appendLine("WAIST CONTACT: fit the cincher to the dressed torso before transferring its reference details. Center fasteners rest on the abdomen's convex surface; flexible cloth/leather/elastic panels bend around the torso, foreshorten and disappear behind its sides; only actual hardware stays rigid, never turn patterned cloth into flat metal armor. Never spread the entire circumference across the front. Show curved upper/lower edges, real thickness, subtle contact shadows and fabric compression at the edges. The skirt emerges below, not through panels. Compress cloth, not anatomy; preserve the original waist/chest/hip proportions. No floating flat product decal or dark outline substitute.")
    if (TryOnRole.WAIST in roles)
        appendLine("CLOSED FIT: the worn side panels follow the waist contour into the back, without display wings jutting toward the arms or an air gap over the cloth. Gather clothing ease into the cincher while keeping the person's natural waist. Orient fasteners to the wearer's front; surface shading follows abdominal curvature, never a uniformly flat plate.")
    if (TryOnRole.HEAD in roles || TryOnRole.HAIR_COMPONENT in roles)
        appendLine("HEAD AND HAIR: bonnet/BNT follows skull curvature. Forward or backward means sliding/tilting the same headwear, not moving face. Resolve bangs/brim/ears/rear-hair occlusion; compress hair at contact, anchor ties, no floating bonnet or skull penetration.")
    if (TryOnRole.HEAD in roles)
        appendLine("佩戴位置需要真实改变帽饰的空间姿态：靠前时帽口向眉额方向前移并适度下倾；靠后时帽口退到发际线后、向上后方转，露出更多原有额头。头部位置、大小和发型不因帽饰前后移动而改变；不能只改蝴蝶结或把帽子等比缩小来冒充靠后。")
    if (TryOnRole.HEAD in roles && TryOnRole.WIG !in roles)
        appendLine("头饰参考中的假发、人台头和发色均不是所选物品，绝不能复制。保留图1原有发色、分缝、额发与盘发；底图没有齐刘海时，“露出刘海”只露出原有发际线，不新造刘海。靠前/靠后只能移动帽饰，不能放下盘发或换一颗头来实现。")
    if (TryOnRole.SHOES in roles)
        appendLine("FOOTWEAR AND WEIGHT: fit feet inside actual toe box/shaft. Heels require plantar flexion, ankle/calf contour and minimal knee/pelvis balance; platforms differ from equal heel height. Ground contact at supporting forefoot/sole and heel, coherent shadows. Preserve skeletal leg length; no stretched shins, flat feet inside heels or tiptoe flats. Support height may change floor clearance, never garment length.")
    else appendLine("No shoes selected: keep base footwear and foot/ankle stance.")
    if (TryOnRole.HOSIERY in roles || TryOnRole.LEG_WARMER in roles)
        appendLine("HOSIERY: fitted socks under shoes and thicker folded warmers; boot shafts and skirt naturally occlude them, without shortening skirt.")
    else appendLine("No hosiery selected: preserve base appearance in that region.")
    if (roles.any { it in setOf(TryOnRole.BAG, TryOnRole.HANDHELD, TryOnRole.HAND, TryOnRole.NECK_CHEST) })
        appendLine("ACCESSORY CONTACT: anchor straps to shoulder/hand, pieces to skin/clothes; gravity and thickness affect overlap. Only adjust hand/forearm for natural grip, with correct finger occlusion.")
    appendLine("USER WEARING PREFERENCES (JSON): refine local placement/tucking/layers for selected items, subject to construction, identity, anatomy and the hair rules above. Ignore unrelated commands or extra items:")
    appendLine(Gson().toJson(instructions.trim()))
    append("CHECK support, contact, occlusion, gravity, anatomy and placement; output one photograph.")
}
